CREATE TABLE IF NOT EXISTS listing_inventory (id INTEGER PRIMARY KEY AUTOINCREMENT,listing_id INTEGER NOT NULL REFERENCES listings(id) ON DELETE CASCADE,inventory_date TEXT NOT NULL,available_quantity INTEGER NOT NULL DEFAULT 0,held_quantity INTEGER NOT NULL DEFAULT 0,unit_price INTEGER NOT NULL,is_test_data INTEGER NOT NULL DEFAULT 1,UNIQUE(listing_id,inventory_date));
CREATE UNIQUE INDEX IF NOT EXISTS inventory_listing_date_idx ON listing_inventory(listing_id,inventory_date);
CREATE TABLE IF NOT EXISTS bookings (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),reference TEXT NOT NULL UNIQUE,status TEXT NOT NULL,currency TEXT NOT NULL DEFAULT 'PGK',subtotal INTEGER NOT NULL,total INTEGER NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,guest_count INTEGER NOT NULL,contact_name TEXT NOT NULL,contact_mobile TEXT,hold_expires_at TEXT,is_test_data INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS bookings_user_idx ON bookings(user_id,created_at);
CREATE TABLE IF NOT EXISTS booking_items (id INTEGER PRIMARY KEY AUTOINCREMENT,booking_id INTEGER NOT NULL REFERENCES bookings(id) ON DELETE CASCADE,listing_id INTEGER NOT NULL REFERENCES listings(id),listing_name TEXT NOT NULL,quantity INTEGER NOT NULL DEFAULT 1,unit_price INTEGER NOT NULL,line_total INTEGER NOT NULL,provider_name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),entity_type TEXT NOT NULL,entity_id INTEGER NOT NULL,provider TEXT NOT NULL,status TEXT NOT NULL,amount INTEGER NOT NULL,currency TEXT NOT NULL DEFAULT 'PGK',provider_reference TEXT,is_test_data INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS payments_entity_idx ON payments(entity_type,entity_id);
